import { useCallback, useEffect, useMemo, useState } from 'react'
import { api } from '../services/api.js'
import { useAuth } from '../auth/useAuth.js'
import { useClassSelection } from '../class/useClassSelection.js'
import { DataTable, Field, Message, PageIntro, Panel, Pill } from '../components/ui.jsx'

export function FeesPage() {
  const { user } = useAuth()
  const { selectedClassId, selectedClass } = useClassSelection()
  const isAdmin = useMemo(() => user?.role === 'admin', [user?.role])
  const [fees, setFees] = useState([])
  const [error, setError] = useState('')
  const [form, setForm] = useState({ student_id: '', amount: '', due_date: '' })

  const load = useCallback(async () => {
    setError('')
    try {
      const res = await api.get('/fees', { params: selectedClassId ? { class_id: selectedClassId } : {} })
      setFees(res.data.fees || [])
    } catch (e) {
      setFees([])
      setError(e?.response?.data?.error || 'Failed to load fees')
    }
  }, [selectedClassId])

  useEffect(() => {
    load()
  }, [load])

  async function addFee(event) {
    event.preventDefault()
    setError('')
    try {
      await api.post('/fees', {
        student_id: Number(form.student_id),
        class_id: Number(selectedClassId),
        amount: Number(form.amount),
        due_date: form.due_date,
      })
      setForm({ student_id: '', amount: '', due_date: '' })
      await load()
    } catch (e) {
      setError(e?.response?.data?.error || 'Failed to add fee')
    }
  }

  async function pay(id) {
    setError('')
    try {
      await api.put(`/fees/pay/${id}`)
      await load()
    } catch (e) {
      setError(e?.response?.data?.error || 'Failed to mark paid')
    }
  }

  return (
    <div className="space-y-6">
      <PageIntro
        eyebrow="Fees"
        title={isAdmin ? 'Track collections with more clarity' : 'Stay on top of your fee status'}
        description={
          isAdmin
            ? 'Create dues, review pending balances, and close the loop on payments for the current class.'
            : 'A cleaner fee ledger makes it easier to see what is pending and what is already settled.'
        }
        action={selectedClass && isAdmin ? <Pill tone="amber">Class {selectedClass.class_name} • {selectedClass.section}</Pill> : null}
      />

      {error ? <Message>{error}</Message> : null}

      {isAdmin ? (
        <Panel title="Create fee entry" subtitle="Record due dates and amounts for students in the active class.">
          <form onSubmit={addFee} className="grid grid-cols-1 gap-4 md:grid-cols-3">
            <Field label="Student ID" value={form.student_id} onChange={(value) => setForm((current) => ({ ...current, student_id: value }))} placeholder="Internal student id" />
            <Field label="Amount" value={form.amount} onChange={(value) => setForm((current) => ({ ...current, amount: value }))} placeholder="4500" />
            <label className="field-shell">
              <span className="field-label">Due Date</span>
              <input type="date" value={form.due_date} onChange={(event) => setForm((current) => ({ ...current, due_date: event.target.value }))} className="field-input" />
            </label>
            <div className="md:col-span-3">
              <button className="app-button">Add fee</button>
            </div>
          </form>
        </Panel>
      ) : null}

      <Panel title="Fee ledger" subtitle={isAdmin ? 'Review payment progress and close pending dues.' : 'Read-only view of your fee records.'}>
        <DataTable
          columns={isAdmin ? ['Student', 'Amount', 'Due', 'Status', 'Action'] : ['Amount', 'Due', 'Status']}
          rows={fees}
          empty="No fee records yet"
          renderRow={(fee) => (
            <tr key={fee.id}>
              {isAdmin ? <td className="font-semibold text-slate-900">{fee.student_name || fee.student_id}</td> : null}
              <td>{Number(fee.amount).toFixed(2)}</td>
              <td>{String(fee.due_date).slice(0, 10)}</td>
              <td>{fee.status === 'paid' ? <Pill tone="emerald">Paid</Pill> : <Pill tone="amber">Pending</Pill>}</td>
              {isAdmin ? (
                <td>
                  {fee.status === 'pending' ? (
                    <button className="app-button-secondary px-3 py-2 text-xs" onClick={() => pay(fee.id)}>
                      Mark paid
                    </button>
                  ) : (
                    <span className="text-sm text-slate-500">Completed</span>
                  )}
                </td>
              ) : null}
            </tr>
          )}
        />
      </Panel>
    </div>
  )
}
